-- -----------------------------------------------------
-- View `agro`.`v_rendimiento_lote`
-- -----------------------------------------------------
DROP TABLE IF EXISTS `agro`.`v_rendimiento_lote`;
USE `agro`;
CREATE  OR REPLACE VIEW v_rendimiento_lote AS
SELECT
    s.campana_id,
    cp.nombre                              AS campana,
    e.nombre                               AS establecimiento,
    l.nombre                               AS lote,
    cu.nombre                              AS cultivo,
    s.fecha_inicio                          AS fecha_siembra,
    co.fecha_inicio                         AS fecha_cosecha,
    co.hectareas,
    -- peso total cosechado
    (SELECT COALESCE(SUM(p.peso_neto), 0)
       FROM pesajes p WHERE p.cosecha_id = co.cosecha_id)  AS peso_total_kg,
	-- rendimiento por hectarea
    ROUND(
        (SELECT COALESCE(SUM(p.peso_neto), 0) FROM pesajes p WHERE p.cosecha_id = co.cosecha_id)
        / NULLIF(co.hectareas, 0), 1
    )                                       AS kg_por_ha
FROM cosechas co
JOIN siembras s          ON s.siembra_id = co.siembra_id
JOIN campanas cp         ON cp.campana_id = s.campana_id
JOIN lotes l              ON l.lote_id = s.lote_id
JOIN establecimientos e  ON e.establecimiento_id = l.establecimiento_id
JOIN insumos i            ON i.insumo_id = s.semilla_insumo_id
JOIN grupos_insumo g      ON g.grupo_id = i.grupo_id
JOIN cultivos cu          ON cu.cultivo_id = g.cultivo_id
WHERE co.eliminado_en IS NULL
  AND s.eliminado_en IS NULL;

-- -----------------------------------------------------
-- View `agro`.`v_trazabilidad_campana`
-- -----------------------------------------------------
DROP TABLE IF EXISTS `agro`.`v_trazabilidad_campana`;
USE `agro`;
CREATE OR REPLACE VIEW `v_trazabilidad_campana` AS
-- ---------------------------------------------------------------
-- Etapa 1: Siembra
-- ---------------------------------------------------------------
SELECT
s.campana_id,
cp.nombre AS campana,
e.establecimiento_id,
e.nombre AS establecimiento,
l.lote_id,
l.nombre AS lote,
1 AS orden_etapa,
'Siembra' AS etapa,
s.fecha_inicio AS fecha,
concat('Semilla: ', ins_sem.nombre) AS detalle,
s.semilla_total_kg AS cantidad,
'kg' AS unidad,
NULL AS contratista,
NULL AS numero_orden,
s.siembra_id
FROM siembras s
JOIN campanas cp ON cp.campana_id = s.campana_id
JOIN lotes l ON l.lote_id = s.lote_id
JOIN establecimientos e ON e.establecimiento_id = l.establecimiento_id
JOIN insumos ins_sem ON ins_sem.insumo_id = s.semilla_insumo_id
WHERE s.eliminado_en IS NULL

UNION ALL

-- ---------------------------------------------------------------
-- Etapa 2: Aplicaciones de insumos (órdenes de trabajo por lote)
-- ---------------------------------------------------------------
SELECT
ot.campana_id,
cp.nombre AS campana,
e.establecimiento_id,
e.nombre AS establecimiento,
l.lote_id,
l.nombre AS lote,
2 AS orden_etapa,
CONCAT('Trabajo - ', lab.nombre) AS etapa,
ot.fecha AS fecha,
ins.nombre AS detalle,
oli.total AS cantidad,
oi.unidad AS unidad,
con.nombre AS contratista,
ot.numero_orden AS numero_orden,
NULL AS siembra_id
FROM ordenes_trabajo ot
JOIN orden_lotes ol ON ol.orden_id = ot.orden_id
JOIN orden_lote_insumos oli ON oli.orden_lote_id = ol.orden_lote_id
JOIN orden_insumos oi ON oi.orden_insumo_id = oli.orden_insumo_id
JOIN insumos ins ON ins.insumo_id = oi.insumo_id
JOIN labores lab ON lab.labor_id = ot.labor_id
JOIN campanas cp ON cp.campana_id = ot.campana_id
JOIN lotes l ON l.lote_id = ol.lote_id
JOIN establecimientos e ON e.establecimiento_id = l.establecimiento_id
JOIN contratistas con ON con.contratista_id = ot.contratista_id
WHERE ot.eliminado_en IS NULL

UNION ALL

-- ---------------------------------------------------------------
-- Etapa 3: Cosecha (con kg netos totales pesados)
-- ---------------------------------------------------------------
SELECT
s.campana_id,
cp.nombre AS campana,
e.establecimiento_id,
e.nombre AS establecimiento,
l.lote_id,
l.nombre AS lote,
3 AS orden_etapa,
'Cosecha' AS etapa,
co.fecha_inicio AS fecha,
CASE 
	WHEN co.humedad IS NULL THEN 'Humedad: sin dato'
    ELSE CONCAT('Humedad: ', co.humedad, '%')
END AS detalle,
(SELECT COALESCE(SUM(p.peso_neto), 0)
   FROM pesajes p
  WHERE p.cosecha_id = co.cosecha_id) AS cantidad,
'kg' AS unidad,
NULL AS contratista,
NULL AS numero_orden,
s.siembra_id
FROM cosechas co
JOIN siembras s ON s.siembra_id = co.siembra_id
JOIN campanas cp ON cp.campana_id = s.campana_id
JOIN lotes l ON l.lote_id = s.lote_id
JOIN establecimientos e ON e.establecimiento_id = l.establecimiento_id
WHERE co.eliminado_en IS NULL
  AND s.eliminado_en IS NULL;
USE `agro`;

DELIMITER $$
USE `agro`$$
CREATE DEFINER = CURRENT_USER TRIGGER  `agro` . `trg_orden_numero_ins` BEFORE INSERT ON `ordenes_trabajo` FOR EACH ROW 
BEGIN 
	IF NEW.numero_orden NOT REGEXP '^[0-9]{2}-[0-9]{2}-[0-9]{4}$' THEN
		SIGNAL SQLSTATE '45000'
			SET MESSAGE_TEXT = 'numero_orden no cumple el formato AA-AA-NNNN';
	END IF;
END$$

USE `agro`$$
CREATE TRIGGER trg_orden_establecimiento_upd
BEFORE UPDATE ON ordenes_trabajo
FOR EACH ROW
BEGIN
    IF NEW.establecimiento_id <> OLD.establecimiento_id AND EXISTS (
        SELECT 1
        FROM orden_lotes ol
        JOIN lotes l ON l.lote_id = ol.lote_id
        WHERE ol.orden_id = OLD.orden_id
          AND l.establecimiento_id <> NEW.establecimiento_id
    ) THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Los lotes no pertenecen al nuevo establecimiento de la orden';
    END IF;
END$$

USE `agro`$$
CREATE DEFINER = CURRENT_USER TRIGGER `agro`.`trg_orden_numero_upd` BEFORE UPDATE ON `ordenes_trabajo` FOR EACH ROW
BEGIN
    IF NEW.numero_orden NOT REGEXP '^[0-9]{2}-[0-9]{2}-[0-9]{4}$' THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'numero_orden no cumple el formato AA-AA-NNNN';
    END IF;
END$$

USE `agro`$$
CREATE TRIGGER trg_orden_lote_establecimiento_ins
BEFORE INSERT ON orden_lotes
FOR EACH ROW
BEGIN
    IF (SELECT establecimiento_id FROM lotes WHERE lote_id = NEW.lote_id) <>
       (SELECT establecimiento_id FROM ordenes_trabajo WHERE orden_id = NEW.orden_id) THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'El lote no pertenece al establecimiento de la orden';
    END IF;
END$$

USE `agro`$$
CREATE TRIGGER trg_orden_lote_establecimiento_upd
BEFORE UPDATE ON orden_lotes
FOR EACH ROW
BEGIN
    IF (SELECT establecimiento_id FROM lotes WHERE lote_id = NEW.lote_id) <>
       (SELECT establecimiento_id FROM ordenes_trabajo WHERE orden_id = NEW.orden_id) THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'El lote no pertenece al establecimiento de la orden';
    END IF;
END$$

USE `agro`$$
CREATE TRIGGER trg_siembra_semilla_ins
BEFORE INSERT ON siembras
FOR EACH ROW
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM insumos i
        JOIN grupos_insumo g ON g.grupo_id = i.grupo_id
        WHERE i.insumo_id = NEW.semilla_insumo_id
          AND g.cultivo_id IS NOT NULL
    ) THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'El insumo seleccionado no es una semilla';
    END IF;
END$$

USE `agro`$$
CREATE DEFINER = CURRENT_USER TRIGGER `agro`.`trg_siembra_fechas_ins` BEFORE INSERT ON `siembras` FOR EACH ROW
BEGIN
    IF NEW.fecha_fin < NEW.fecha_inicio THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'fecha_fin no puede ser anterior a fecha_inicio';
    END IF;
END$$

USE `agro`$$
CREATE TRIGGER trg_siembra_semilla_upd
BEFORE UPDATE ON siembras
FOR EACH ROW
BEGIN
    IF NEW.semilla_insumo_id <> OLD.semilla_insumo_id AND NOT EXISTS (
        SELECT 1
        FROM insumos i
        JOIN grupos_insumo g ON g.grupo_id = i.grupo_id
        WHERE i.insumo_id = NEW.semilla_insumo_id
          AND g.cultivo_id IS NOT NULL
    ) THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'El insumo seleccionado no es una semilla';
    END IF;
END$$

USE `agro`$$
CREATE DEFINER = CURRENT_USER TRIGGER `agro`.`trg_siembra_fechas_upd` BEFORE UPDATE ON `siembras` FOR EACH ROW
BEGIN
    IF NEW.fecha_fin < NEW.fecha_inicio THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'fecha_fin no puede ser anterior a fecha_inicio';
    END IF;
END$$

USE `agro`$$
CREATE DEFINER = CURRENT_USER TRIGGER `agro`.`trg_cosecha_fechas_ins` BEFORE INSERT ON `cosechas` FOR EACH ROW
BEGIN
    IF NEW.fecha_fin < NEW.fecha_inicio THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'fecha_fin no puede ser anterior a fecha_inicio';
    END IF;
END$$

USE `agro`$$
CREATE DEFINER = CURRENT_USER TRIGGER `agro`.`trg_cosecha_fechas_upd` BEFORE UPDATE ON `cosechas` FOR EACH ROW
BEGIN
    IF NEW.fecha_fin < NEW.fecha_inicio THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'fecha_fin no puede ser anterior a fecha_inicio';
    END IF;
END$$

USE `agro`$$
CREATE DEFINER = CURRENT_USER TRIGGER `agro`.`trg_pesaje_pesos_ins` BEFORE INSERT ON `pesajes` FOR EACH ROW
BEGIN
    IF NOT (NEW.peso_bruto > 0 AND NEW.peso_tara > 0 AND NEW.peso_bruto > NEW.peso_tara) THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Pesaje inválido: bruto y tara deben ser positivos y bruto > tara';
    END IF;
END$$

USE `agro`$$
CREATE DEFINER = CURRENT_USER TRIGGER `agro`.`trg_pesaje_pesos_upd` BEFORE UPDATE ON `pesajes` FOR EACH ROW
BEGIN
    IF NOT (NEW.peso_bruto > 0 AND NEW.peso_tara > 0 AND NEW.peso_bruto > NEW.peso_tara) THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Pesaje inválido: bruto y tara deben ser positivos y bruto > tara';
    END IF;
END$$


